/**
 * The eighty-one provinces of Türkiye, as shapes.
 *
 * Generated, not written. Same source and same build as the districts in
 * `izmir.ts`, one administrative level up:
 *
 *   unzip -o tur.zip tur_admin1.geojson
 *   # carry adm1_pcode through as "pcode"
 *   npx mapshaper@0.6 turkey.geojson -simplify 0.6pct keep-shapes  *     -proj "+proj=lcc +lat_1=37 +lat_2=41 +lon_0=35 +lat_0=39"  *     -o format=svg id-field=pcode width=900 turkey.svg
 *
 * (0.6pct written out because a per-cent sign would close this comment.)
 *
 * Simplified harder than the districts — 0.6 against 3 — because this layer
 * draws the whole country in the same 544px the province gets, so the detail
 * would not survive the scale anyway. 84 KB at 1 per cent, 54 KB here, and at
 * this size the two are indistinguishable on screen.
 *
 * The names are written out for the reason given in `izmir.ts`: the source's
 * Turkish field is mangled the same way at this level — "İzmi̇r" with a
 * combining dot, "Şanliurfa" for Şanlıurfa, "Aydin" for Aydın, "Ağri" for Ağrı.
 * The dotless ı is not in the file and cannot be derived from it.
 */
import type { PlaceShape } from './shape.js';

/** The pixel space the paths are drawn in, from the projection above. */
